import { useEffect, useMemo, useState } from 'react';
import { useLanguage } from '../../../../core/i18n';
import {
  EVENTS_LIST_PAGE_SIZE,
  getCachedHomeEvents,
  getCachedPublicHomeEvents,
  getCurrentEventsUser,
  getHomeEvents,
  getPublicHomeEvents,
  registerHomeEvent,
  sortEventsForHighlights,
} from '../../home/services/homeEventsService';

const initialState = {
  events: [],
  pagination: {
    pagina_actual: 1,
    por_pagina: EVENTS_LIST_PAGE_SIZE,
    total: 0,
    ultima_pagina: 1,
    desde: null,
    hasta: null,
  },
};

function translateKnownEventError(message, t) {
  const knownErrors = {
    'No se pudieron cargar los eventos.': 'public.events.loadError',
    'No se pudieron cargar los eventos publicos.': 'public.events.loadError',
    'No se pudo inscribir al evento.': 'public.events.registrationError',
  };

  return knownErrors[message] ? t(knownErrors[message]) : message;
}

function normalizePagination(pagination = {}, page = 1) {
  const currentPage = Number(pagination.pagina_actual || pagination.current_page || page) || 1;
  const perPage = Number(
    pagination.por_pagina || pagination.per_page || EVENTS_LIST_PAGE_SIZE,
  ) || EVENTS_LIST_PAGE_SIZE;
  const total = Number(pagination.total || 0) || 0;
  const reportedLastPage = Number(pagination.ultima_pagina || pagination.last_page || 0);
  const lastPage = reportedLastPage > 0
    ? reportedLastPage
    : Math.max(1, Math.ceil(total / Math.max(1, perPage)));

  return {
    ...initialState.pagination,
    ...pagination,
    pagina_actual: Math.min(Math.max(1, currentPage), lastPage),
    por_pagina: perPage,
    total,
    ultima_pagina: lastPage,
  };
}

function getInitialPage(page) {
  try {
    let cached;

    try {
      getCurrentEventsUser();
      cached = getCachedHomeEvents({
        allowStale: true,
        page,
        perPage: EVENTS_LIST_PAGE_SIZE,
        scope: 'events-page',
      });
    } catch {
      cached = getCachedPublicHomeEvents({
        allowStale: true,
        page,
        perPage: EVENTS_LIST_PAGE_SIZE,
        scope: 'events-page-public',
      });
    }

    if (!cached?.value) return initialState;

    return {
      ...initialState,
      ...cached.value,
      pagination: normalizePagination(cached.value.pagination, page),
    };
  } catch {
    return initialState;
  }
}

export default function useEventsPage() {
  const { t } = useLanguage();
  const [page, setPage] = useState(1);
  const [data, setData] = useState(() => getInitialPage(1));
  const [loading, setLoading] = useState(() => getInitialPage(1).events.length === 0);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [registeringId, setRegisteringId] = useState(null);
  const [authRequired, setAuthRequired] = useState(false);

  useEffect(() => {
    let mounted = true;

    async function loadPage() {
      let cached = null;
      let authenticated = true;

      try {
        getCurrentEventsUser();
      } catch {
        authenticated = false;
      }

      try {
        cached = authenticated ? getCachedHomeEvents({
          allowStale: true,
          page,
          perPage: EVENTS_LIST_PAGE_SIZE,
          scope: 'events-page',
        }) : getCachedPublicHomeEvents({
          allowStale: true,
          page,
          perPage: EVENTS_LIST_PAGE_SIZE,
          scope: 'events-page-public',
        });

        if (cached?.value && mounted) {
          setData({
            ...initialState,
            ...cached.value,
            pagination: normalizePagination(cached.value.pagination, page),
          });
          setLoading(false);
        }

        const result = authenticated ? await getHomeEvents({
          page,
          perPage: EVENTS_LIST_PAGE_SIZE,
          scope: 'events-page',
        }) : await getPublicHomeEvents({
          page,
          perPage: EVENTS_LIST_PAGE_SIZE,
          scope: 'events-page-public',
        });

        if (mounted) {
          setData({
            ...initialState,
            ...result,
            pagination: normalizePagination(result.pagination, page),
          });
          setAuthRequired(false);
          setError('');
        }
      } catch (err) {
        if (!mounted) return;

        const message = translateKnownEventError(err?.message, t) || t('public.events.loadError');
        const isAuthError = message.toLowerCase().includes('sesion')
          || message.toLowerCase().includes('autentic')
          || message.toLowerCase().includes('no autorizado');

        setAuthRequired(isAuthError && authenticated);
        if (!cached?.value) {
          setError(isAuthError ? '' : message);
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    }

    setLoading(true);
    loadPage();

    return () => {
      mounted = false;
    };
  }, [page, t]);

  const events = useMemo(() => sortEventsForHighlights(data.events), [data.events]);
  const pagination = useMemo(
    () => normalizePagination(data.pagination, page),
    [data.pagination, page],
  );

  const register = async (event) => {
    if (!event?.id) return null;

    setRegisteringId(event.id);
    setNotice('');
    setError('');

    try {
      const payload = await registerHomeEvent(event.id, {
        page,
        perPage: EVENTS_LIST_PAGE_SIZE,
        scope: 'events-page',
      });

      if (payload?.refreshed) {
        setData({
          ...initialState,
          ...payload.refreshed,
          pagination: normalizePagination(payload.refreshed.pagination, page),
        });
      }

      setNotice(payload?.mensaje || payload?.message || t('public.events.registrationSuccess'));
      return payload;
    } catch (err) {
      setError(translateKnownEventError(err?.message, t) || t('public.events.registrationError'));
      return null;
    } finally {
      setRegisteringId(null);
    }
  };

  const refresh = async () => {
    setLoading(true);
    setError('');

    try {
      let result;

      try {
        getCurrentEventsUser();
        result = await getHomeEvents({
          force: true,
          page,
          perPage: EVENTS_LIST_PAGE_SIZE,
          scope: 'events-page',
        });
      } catch {
        result = await getPublicHomeEvents({
          force: true,
          page,
          perPage: EVENTS_LIST_PAGE_SIZE,
          scope: 'events-page-public',
        });
      }

      setData({
        ...initialState,
        ...result,
        pagination: normalizePagination(result.pagination, page),
      });
      setNotice(t('public.events.refreshSuccess'));
    } catch (err) {
      setError(translateKnownEventError(err?.message, t) || t('public.events.refreshError'));
    } finally {
      setLoading(false);
    }
  };

  return {
    authRequired,
    error,
    events,
    goToPage: setPage,
    loading,
    notice,
    page,
    pagination,
    refresh,
    register,
    registeringId,
    setNotice,
  };
}
